package com.edufox.schoolerp.fee;

import com.edufox.schoolerp.config.DatabaseWriteGuard;
import io.jsonwebtoken.Claims;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.apache.poi.ss.usermodel.*;
import java.io.InputStream;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.*;

/** Direct Java replacement for the Fee -> Work ASPX handlers. */
@RestController
@RequestMapping("/api/fees/work")
@RequiredArgsConstructor
@PreAuthorize("hasRole('FACULTY')")
public class FeeWorkController {
    private final JdbcTemplate jdbc;
    private final DatabaseWriteGuard writeGuard;
    private static Claims claims(Authentication a){return (Claims)a.getDetails();}
    private static String school(Authentication a){return text(claims(a).get("schoolId",String.class));}
    private static String staff(Authentication a){return text(claims(a).get("staffUid",String.class));}
    private static String text(Object v){return v==null?"":String.valueOf(v).trim();}
    private static BigDecimal money(Object v){return text(v).isBlank()?BigDecimal.ZERO:new BigDecimal(text(v));}
    private static Map<String,Object> out(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i+1<v.length;i+=2)m.put(String.valueOf(v[i]),v[i+1]);return m;}
    private String session(Object requested,String sc){if(!text(requested).isBlank())return text(requested);List<Map<String,Object>>r=jdbc.queryForList("SELECT TOP 1 session FROM TB_Session WHERE school_id=? ORDER BY CASE WHEN status='Default' THEN 0 ELSE 1 END,id DESC",sc);return r.isEmpty()?"":text(r.get(0).get("session"));}

    @GetMapping("/miscellaneous")
    public Map<String,Object> miscellaneous(@RequestParam(required=false)String session,Authentication a){
        String sc=school(a),ses=session(session,sc);
        return out("session",ses,"sessions",jdbc.queryForList("SELECT session AS value,session AS label FROM TB_Session WHERE school_id=? ORDER BY id DESC",sc),"heads",jdbc.queryForList("SELECT miscellaneous_type_id AS id,miscellaneous_type AS name FROM fee_miscellaneous_head WHERE school_id=? AND session=? ORDER BY miscellaneous_type",sc,ses),"records",jdbc.queryForList("SELECT TOP(500) p.row_id AS id,COALESCE(p.pay_date,p.paymentdate,p.deposit_date) AS payDate,COALESCE(h.miscellaneous_type,'Miscellaneous') AS headName,p.admission_no AS admissionNo,COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'') AS studentName,TRY_CONVERT(decimal(18,2),p.amount) AS amount,COALESCE(p.feeremark,'') AS remark,COALESCE(p.receipt_no,p.receiptno) AS receiptNo,p.session FROM fee_payment_detail p LEFT JOIN fee_miscellaneous_head h ON TRY_CONVERT(int,p.miscellaneous_fee)=h.miscellaneous_type_id AND h.school_id=p.school_id AND h.session=p.session LEFT JOIN TB_StudentMaster sm ON sm.school_id=p.school_id AND sm.registration_no=p.admission_no LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no WHERE p.school_id=? AND p.session=? AND (p.miscellaneous_fee IS NOT NULL OR p.fee_type='Miscellaneous') ORDER BY COALESCE(p.pay_date,p.paymentdate,p.deposit_date) DESC,p.row_id DESC",sc,ses));
    }
    @GetMapping("/miscellaneous/{studentId}/receipt")
    public Map<String,Object> miscellaneousReceipt(@PathVariable String studentId,@RequestParam String receiptNo,Authentication a){
        String sc=school(a);List<Map<String,Object>> student=jdbc.queryForList("SELECT TOP 1 sm.registration_no AS admNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS name,COALESCE(so.father_name,'') AS fatherName FROM TB_StudentMaster sm LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no WHERE sm.school_id=? AND CAST(sm.stu_id AS varchar(50))=?",sc,studentId);
        List<Map<String,Object>> header=jdbc.queryForList("SELECT TOP 1 COALESCE(receipt_no,receiptno) AS receiptNo,COALESCE(pay_date,paymentdate,deposit_date) AS paymentDate,admno,mop,transaction_no AS transactionNo,amount,fee_type,deposit_by AS depositBy,uid FROM fee_payment_detail WHERE school_id=? AND (CAST(stu_id AS varchar(50))=? OR admission_no=(SELECT TOP 1 registration_no FROM TB_StudentMaster WHERE school_id=? AND CAST(stu_id AS varchar(50))=?)) AND COALESCE(receipt_no,receiptno)=? ORDER BY row_id DESC",sc,studentId,sc,studentId,receiptNo);
        if(header.isEmpty())throw new IllegalArgumentException("Receipt not found");
        return out("header",header.get(0),"student",student,"lines",jdbc.queryForList("SELECT COALESCE(h.miscellaneous_type,'Miscellaneous') AS feeHead,d.amount,d.pay_date AS paymentDate,d.remarks AS remark FROM Fee_miscellaneous_fee_deposit d LEFT JOIN fee_miscellaneous_head h ON h.school_id=d.school_id AND h.session=d.session AND h.miscellaneous_type_id=d.miscellaneous_type_id WHERE d.school_id=? AND CAST(d.stu_id AS varchar(50))=? AND d.receipt_no=? ORDER BY d.miscellaneous_fee_id",sc,studentId,receiptNo));
    }
    @PostMapping("/miscellaneous") @Transactional
    public Map<String,Object> addMiscellaneous(@RequestBody Map<String,Object>r,Authentication a){
        writeGuard.requireWritable();String sc=school(a),ses=session(r.get("session"),sc),adm=text(r.get("admissionNo"));
        Map<String,Object>st=jdbc.queryForMap("SELECT TOP 1 stu_id,uid FROM TB_StudentMaster WHERE school_id=? AND registration_no=? AND session=?",sc,adm,ses);
        BigDecimal amount=money(r.get("amount")),late=money(r.get("lateFee"));if(truthy(r.get("waiveOff")))late=BigDecimal.ZERO;BigDecimal total=amount.add(late);if(total.signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero");
        String date=text(r.get("paymentDate"));if(date.isBlank())date=LocalDate.now().toString();String receipt=text(r.get("receiptNo"));if(receipt.isBlank())receipt=nextReceipt(sc,ses,"Miscellaneous");String uid=UUID.randomUUID().toString();String mop=text(r.get("mop"));if(mop.isBlank())mop="Cash";String txnDate=text(r.get("transactionDate"));if(txnDate.isBlank())txnDate=date;
        jdbc.update("INSERT INTO fee_payment_detail(financial_year,school_id,admno,mop,fee_type,transaction_no,Bank_id,amount,paymentdate,receiptno,uid,status,deposit_by,deposit_date,transaction_date,miscellaneous_fee,feeremark,admission_no,created_by,created_on,pay_date,pay_mode,receipt_no,session,stu_id,fee_type_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",ses,sc,adm,mop,"Miscellaneous",text(r.get("transactionNo")),text(r.get("bankId")),total.toPlainString(),date,receipt,uid,"1",staff(a),date,txnDate,text(r.get("headId")),text(r.get("remark")),adm,staff(a),LocalDateTime.now(),date,mop,receipt,ses,st.get("stu_id"),"0");
        jdbc.update("INSERT INTO Fee_miscellaneous_fee_deposit(miscellaneous_type_id,miscellaneous_fee_id,stu_id,amount,school_id,session,created_by,created_date,receipt_no,pay_date,remarks,uid,bankId,pay_mode,txnNo,txnDate,stuUID) VALUES(?,?,?,?,?,?,?,GETDATE(),?,?,?,?,?,?,?,?,?)",i(r.get("headId")),nextMiscId(sc),st.get("stu_id"),total,sc,ses,staff(a),receipt,date,text(r.get("remark")),uid,i(r.get("bankId")),mop,text(r.get("transactionNo")),txnDate,st.get("uid"));
        return out("message","Miscellaneous fee saved","receiptNo",receipt,"uid",uid,"amount",total);
    }
    @PutMapping("/miscellaneous/{id}") @Transactional
    public Map<String,Object> updateMiscellaneous(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE fee_miscellaneous_head SET miscellaneous_type=? WHERE miscellaneous_type_id=? AND school_id=? AND session=?",text(r.get("name")).toUpperCase(),id,school(a),text(r.get("session")));return out("message","Miscellaneous head updated");}

    /** Java equivalent of define_miscellaneous: setup page only creates/edits
     * the miscellaneous head; depositing its amount is handled separately. */
    @PostMapping("/miscellaneous/head") @Transactional
    public Map<String,Object> addMiscellaneousHead(@RequestBody Map<String,Object>r,Authentication a){
        writeGuard.requireWritable();String sc=school(a),ses=session(r.get("session"),sc),name=text(r.get("name")).toUpperCase();
        if(name.isBlank())throw new IllegalArgumentException("Miscellaneous head is required");
        Integer existing=jdbc.queryForObject("SELECT TOP 1 miscellaneous_type_id FROM fee_miscellaneous_head WHERE school_id=? AND session=? AND UPPER(miscellaneous_type)=?",Integer.class,sc,ses,name);
        if(existing!=null)throw new IllegalArgumentException("Miscellaneous fee already exists");
        Integer id=jdbc.queryForObject("SELECT ISNULL(MAX(miscellaneous_type_id),0)+1 FROM fee_miscellaneous_head WHERE school_id=?",Integer.class,sc);
        jdbc.update("INSERT INTO fee_miscellaneous_head(miscellaneous_type_id,miscellaneous_type,school_id,session,created_by,created_date) VALUES(?,?,?,?,?,GETDATE())",id,name,sc,ses,staff(a));
        return out("message","Record saved successfully","id",id);
    }

    @PutMapping("/miscellaneous/head/{id}") @Transactional
    public Map<String,Object> updateMiscellaneousHead(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){
        writeGuard.requireWritable();String sc=school(a),ses=session(r.get("session"),sc),name=text(r.get("name")).toUpperCase();
        if(name.isBlank())throw new IllegalArgumentException("Miscellaneous head is required");
        Integer duplicate=jdbc.queryForObject("SELECT TOP 1 miscellaneous_type_id FROM fee_miscellaneous_head WHERE school_id=? AND session=? AND UPPER(miscellaneous_type)=? AND miscellaneous_type_id<>?",Integer.class,sc,ses,name,id);
        if(duplicate!=null)throw new IllegalArgumentException("Miscellaneous fee already exists");
        jdbc.update("UPDATE fee_miscellaneous_head SET miscellaneous_type=? WHERE miscellaneous_type_id=? AND school_id=? AND session=?",name,id,sc,ses);
        return out("message","Record updated successfully");
    }

    @GetMapping("/refundable")
    public Map<String,Object> refundable(@RequestParam String admissionNo,@RequestParam(required=false)String session,Authentication a){String sc=school(a),adm=text(admissionNo),ses=session(session,sc);List<Map<String,Object>>stu=jdbc.queryForList("SELECT TOP 1 sm.stu_id AS studentId,sm.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS name,COALESCE(so.father_name,'') AS fatherName,COALESCE(cn.class_name,'')+' ('+COALESCE(cl.section,'')+')' AS className FROM TB_StudentMaster sm JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE sm.school_id=? AND sm.registration_no=? ORDER BY sm.session DESC",sc,adm);if(stu.isEmpty())return out("session",ses,"student",null,"heads",List.of(),"deposit",BigDecimal.ZERO,"records",List.of());Object sid=stu.get(0).get("studentId");BigDecimal dep=jdbc.queryForObject("SELECT COALESCE(SUM(l.receive_amount),0) FROM fee_student_ledger l WHERE l.school_id=? AND l.stu_id=? AND l.fee_head_id IN (SELECT fee_head_id FROM fee_head_master WHERE school_id=? AND isRefundable=1 AND status=1)",BigDecimal.class,sc,sid,sc);return out("session",ses,"student",stu.get(0),"heads",jdbc.queryForList("SELECT fee_head_id AS id,fee_head AS name FROM fee_head_master WHERE isRefundable=1 AND status=1 AND school_id=? AND session=? ORDER BY fee_head",sc,ses),"deposit",dep==null?BigDecimal.ZERO:dep,"records",jdbc.queryForList("SELECT r.id,r.RefundAmount AS deductionAmount,r.Refund AS reason,r.created_date AS date,r.registration_no AS admissionNo,r.session,r.RefId AS feeHeadId,COALESCE(h.fee_head,'') AS headName FROM Fee_Refund r LEFT JOIN fee_head_master h ON h.fee_head_id=r.RefId AND h.school_id=r.school_id AND h.session=r.session WHERE r.school_id=? AND r.registration_no=? AND r.session=? ORDER BY r.id DESC",sc,adm,ses));}
    @PostMapping("/refundable") @Transactional
    public Map<String,Object> addRefundable(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),ses=session(r.get("session"),sc),adm=text(r.get("admissionNo"));BigDecimal amt=money(r.get("amount"));if(amt.signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero");Map<String,Object>st=jdbc.queryForMap("SELECT TOP 1 uid FROM TB_StudentMaster WHERE school_id=? AND registration_no=? AND session=?",sc,adm,ses);jdbc.update("INSERT INTO Fee_Refund(student_unique_id,RefundAmount,Refund,RefId,school_id,session,created_date,created_by,registration_no) VALUES(?,?,?,?,?,?,GETDATE(),?,?)",st.get("uid"),amt,text(r.get("reason")),r.get("headId"),sc,ses,staff(a),adm);return out("message","Refundable deduction saved");}
    @DeleteMapping("/refundable/{id}") @Transactional
    public Map<String,Object> deleteRefundable(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("DELETE FROM Fee_Refund WHERE id=? AND school_id=?",id,school(a));return out("message","Refundable deduction deleted");}

    @GetMapping("/waveoff")
    public Map<String,Object> waveoff(@RequestParam String admissionNo,@RequestParam(required=false)String session,Authentication a){String sc=school(a),ses=session(session,sc);return out("session",ses,"rows",jdbc.queryForList("SELECT l.id,l.installment_no AS installmentNo,CAST(l.installment_no AS varchar(20)) AS installmentName,l.fee_head_id AS feeHeadId,COALESCE(h.display_fee_head,h.fee_head,'') AS feeHead,COALESCE(l.balance,0) AS balance,COALESCE(l.concession,0) AS waveOffAmount FROM fee_student_ledger l JOIN TB_StudentMaster sm ON sm.school_id=l.school_id AND sm.stu_id=l.stu_id LEFT JOIN fee_head_master h ON h.school_id=l.school_id AND h.session=l.session AND h.fee_head_id=l.fee_head_id WHERE l.school_id=? AND l.session=? AND sm.registration_no=? AND COALESCE(l.balance,0)>0 ORDER BY l.installment_no,l.fee_head_id",sc,ses,text(admissionNo)));}
    @PostMapping("/waveoff") @Transactional
    public Map<String,Object> saveWaveoff(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),ses=session(r.get("session"),sc);Object list=r.get("rows");if(!(list instanceof List<?> rows))throw new IllegalArgumentException("Select at least one fee head");int count=0;for(Object raw:rows){if(!(raw instanceof Map<?,?>m))continue;int id=Integer.parseInt(text(m.get("id")));BigDecimal v=money(m.get("amount"));if(v.signum()<=0)continue;if(jdbc.update("UPDATE fee_student_ledger SET concession=COALESCE(concession,0)+?,balance=CASE WHEN COALESCE(balance,0)>=? THEN balance-? ELSE 0 END WHERE id=? AND school_id=? AND session=? AND COALESCE(balance,0)>=?",v,v,v,id,sc,ses,v)==1)count++;}return out("message","Wave off saved","count",count);}

    @GetMapping("/late-deposits")
    public Map<String,Object> lateDeposits(@RequestParam String admissionNo,@RequestParam(required=false)String session,Authentication a){String sc=school(a),ses=session(session,sc);return out("session",ses,"rows",jdbc.queryForList("SELECT d.id,d.stu_id AS studentId,d.inst_no AS installmentNo,COALESCE(d.late_fee,0) AS lateFee,COALESCE(d.dip_amt,0) AS receiveAmount,COALESCE(d.late_fee,0)-COALESCE(d.dip_amt,0) AS balance,d.pay_date AS payDate FROM stu_fee_deposit d JOIN TB_StudentMaster sm ON sm.school_id=d.school_id AND sm.stu_id=d.stu_id WHERE d.school_id=? AND d.session=? AND sm.registration_no=? AND COALESCE(d.late_fee,0)>0 ORDER BY d.inst_no",sc,ses,text(admissionNo)));}
    @PostMapping("/late-deposits") @Transactional
    public Map<String,Object> depositLate(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),ses=session(r.get("session"),sc),adm=text(r.get("admissionNo"));BigDecimal amt=money(r.get("amount"));if(amt.signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero");Map<String,Object>st=jdbc.queryForMap("SELECT TOP 1 stu_id FROM TB_StudentMaster WHERE school_id=? AND registration_no=? AND session=?",sc,adm,ses);String date=text(r.get("paymentDate"));if(date.isBlank())date=LocalDate.now().toString();String uid=UUID.randomUUID().toString();jdbc.update("INSERT INTO stu_fee_deposit(stu_id,inst_no,pay_mode,pay_status,pay_date,dip_amt,created_date,created_by,school_id,session,uid,transaction_date,late_fee,fee_type,receipt_no,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",st.get("stu_id"),r.get("installmentNo"),"Cash","Success",date,amt,LocalDateTime.now(),staff(a),sc,ses,uid,date,amt,r.get("feeType"),text(r.get("receiptNo")),"1");return out("message","Late fee deposited","uid",uid);}

    @GetMapping("/excel/uploads")
    public List<Map<String,Object>> excelUploads(@RequestParam(required=false)String session,Authentication a){String sc=school(a),ses=session(session,sc);return jdbc.queryForList("SELECT guid,MAX(title) AS title,MAX(month_id) AS monthId,MAX(mode) AS mode,MAX(bank_id) AS bankId,MAX(FileTYPE) AS fileType,MAX(created_date) AS postedDate,COUNT(*) AS totalCount,SUM(CASE WHEN ISNULL(reg_no,'')='' OR ISNULL(class,'')='' THEN 1 ELSE 0 END) AS failedCount FROM fee_excelrecord WHERE school_id=? AND session=? AND ISNULL(deletestatus,0)=0 GROUP BY guid ORDER BY MAX(created_date) DESC",sc,ses);}
    @GetMapping("/excel/uploads/{guid}/failed")
    public List<Map<String,Object>> failedExcel(@PathVariable String guid,Authentication a){return jdbc.queryForList("SELECT id,reg_no AS regNo,stu_name AS studentName,class,amount,TRANSECTION_NO AS transactionNo,Remark AS remark FROM fee_excelrecord WHERE school_id=? AND guid=? AND (ISNULL(reg_no,'')='' OR ISNULL(class,'')='') ORDER BY id",school(a),guid);}
    @PutMapping("/excel/records/{id}") @Transactional
    public Map<String,Object> updateExcel(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE fee_excelrecord SET reg_no=?,class=?,Remark=?,adjust_date=GETDATE(),adjust_by=? WHERE id=? AND school_id=?",text(r.get("regNo")),text(r.get("className")),text(r.get("remark")),staff(a),id,school(a));return out("message","Excel record updated");}
    @DeleteMapping("/excel/uploads/{guid}") @Transactional
    public Map<String,Object> deleteExcel(@PathVariable String guid,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE fee_excelrecord SET deletestatus=1,DeleteDate=GETDATE(),Deleteby=? WHERE school_id=? AND guid=?",staff(a),school(a),guid);return out("message","Excel upload deleted");}
    @PostMapping("/excel/upload") @Transactional
    public Map<String,Object> uploadExcel(@RequestParam String session,@RequestParam String title,@RequestParam(required=false)String monthId,@RequestParam String mode,@RequestParam(required=false)Integer bankId,@RequestParam(required=false)Integer fileType,@RequestPart MultipartFile file,Authentication a)throws Exception{writeGuard.requireWritable();if(file.isEmpty())throw new IllegalArgumentException("Select an Excel file");String sc=school(a),guid=UUID.randomUUID().toString();int count=0;DataFormatter f=new DataFormatter();try(InputStream in=file.getInputStream();Workbook wb=WorkbookFactory.create(in)){Sheet sh=wb.getSheetAt(0);Map<String,Integer> h=new HashMap<>();Row head=sh.getRow(0);if(head!=null)for(Cell c:head)h.put(f.formatCellValue(c).trim().toLowerCase(),c.getColumnIndex());for(int n=1;n<=sh.getLastRowNum();n++){Row row=sh.getRow(n);if(row==null)continue;String reg=cell(row,h,"admission no",f),name=cell(row,h,"student name",f),amt=cell(row,h,"amount",f),date=cell(row,h,"paid date",f),pay=cell(row,h,"pay mode",f),txn=cell(row,h,"bank ref no",f);jdbc.update("INSERT INTO fee_excelrecord(reg_no,stu_name,amount,TYPE,TRANSECTION_NO,status_date,STATUS,school_id,session,date1,month_id,title,guid,mode,bank_id,FileTYPE,created_date,created_by,deletestatus) VALUES(?,?,?,?,?,?,0,?,?,?,?,?,?,?,?,?,GETDATE(),?,0)",reg,name,amt,pay,txn,date,sc,session,date,monthId,title,guid,mode,bankId,fileType==null?1:fileType,staff(a));count++;}}return out("message","Excel uploaded","guid",guid,"count",count);}
    private static String cell(Row r,Map<String,Integer>h,String key,DataFormatter f){Integer i=h.get(key.toLowerCase());return i==null?"":f.formatCellValue(r.getCell(i));}
    @GetMapping("/settlement") public List<Map<String,Object>> settlement(@RequestParam(required=false)String session,Authentication a){return excelUploads(session,a);}
    @GetMapping("/settlement/{guid}/failed") public List<Map<String,Object>> settlementFailed(@PathVariable String guid,Authentication a){return failedExcel(guid,a);}

    @GetMapping("/late-report")
    public List<Map<String,Object>> lateReport(@RequestParam(required=false)String session,@RequestParam(required=false)Integer classId,@RequestParam(required=false)String admissionNo,Authentication a){String sc=school(a),ses=session(session,sc),q="SELECT sm.registration_no AS admissionNo,sm.stu_id AS studentId,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,COALESCE(cn.class_name,'')+' ('+COALESCE(cl.section,'')+')' AS className,d.inst_no AS installmentNo,SUM(COALESCE(d.late_fee,0)) AS lateFee,SUM(COALESCE(d.dip_amt,0)) AS received,SUM(COALESCE(d.late_fee,0)-COALESCE(d.dip_amt,0)) AS balance FROM stu_fee_deposit d JOIN TB_StudentMaster sm ON sm.school_id=d.school_id AND sm.stu_id=d.stu_id LEFT JOIN student_other_info so ON so.school_id=sm.school_id AND so.registration_no=sm.registration_no LEFT JOIN class_name cn ON cn.school_id=sm.school_id AND cn.id=sm.class_id LEFT JOIN TB_Class cl ON cl.school_id=sm.school_id AND cl.sec_id=sm.sec_id WHERE d.school_id=? AND d.session=? AND COALESCE(d.late_fee,0)>0";List<Object>p=new ArrayList<>(List.of(sc,ses));if(classId!=null&&classId>0){q+=" AND sm.class_id=?";p.add(classId);}if(!text(admissionNo).isBlank()){q+=" AND sm.registration_no LIKE ?";p.add("%"+text(admissionNo)+"%");}return jdbc.queryForList(q+" GROUP BY sm.registration_no,sm.stu_id,so.first_name,so.last_name,so.father_name,cn.class_name,cl.section,d.inst_no ORDER BY className,studentName",p.toArray());}
    @PostMapping("/late-report/adjust") @Transactional
    public Map<String,Object> adjustLate(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();BigDecimal v=money(r.get("amount"));if(v.signum()<=0)throw new IllegalArgumentException("Adjustment must be greater than zero");BigDecimal current=jdbc.queryForObject("SELECT COALESCE(SUM(late_fee),0) FROM stu_fee_deposit WHERE school_id=? AND session=? AND stu_id=(SELECT TOP 1 stu_id FROM TB_StudentMaster WHERE school_id=? AND registration_no=?) AND inst_no=?",BigDecimal.class,school(a),text(r.get("session")),school(a),text(r.get("admissionNo")),r.get("installmentNo"));if(current==null||v.compareTo(current)>0)throw new IllegalArgumentException("Decrease amount cannot be greater than the current late fee");int n=jdbc.update("UPDATE stu_fee_deposit SET late_fee=CASE WHEN COALESCE(late_fee,0)>=? THEN late_fee-? ELSE 0 END WHERE school_id=? AND session=? AND stu_id=(SELECT TOP 1 stu_id FROM TB_StudentMaster WHERE school_id=? AND registration_no=?) AND inst_no=?",v,v,school(a),text(r.get("session")),school(a),text(r.get("admissionNo")),r.get("installmentNo"));return out("message","Late fee adjusted","updated",n);}

    private static int i(Object v){return text(v).isBlank()?0:Integer.parseInt(text(v));}
    private static boolean truthy(Object v){String s=text(v);return "1".equals(s)||"true".equalsIgnoreCase(s)||"yes".equalsIgnoreCase(s);}
    private int nextMiscId(String sc){Integer id=jdbc.queryForObject("SELECT ISNULL(MAX(miscellaneous_fee_id),0)+1 FROM Fee_miscellaneous_fee_deposit WHERE school_id=?",Integer.class,sc);return id==null?1:id;}
    private String nextReceipt(String sc,String ses,String feeType){List<Map<String,Object>> cfg=jdbc.queryForList("SELECT TOP 1 ReceiptFeeTypeSeriesMode,ResetReceiptSequenceEachFY FROM configuration WHERE school_id=?",sc);boolean byType=!cfg.isEmpty()&&truthy(cfg.get(0).get("ReceiptFeeTypeSeriesMode")),byYear=!cfg.isEmpty()&&truthy(cfg.get(0).get("ResetReceiptSequenceEachFY"));StringBuilder q=new StringBuilder("SELECT ISNULL(MAX(TRY_CONVERT(BIGINT,receiptno)),0)+1 FROM fee_payment_detail WHERE school_id=? AND status='1'");List<Object>p=new ArrayList<>(List.of(sc));if(byYear){q.append(" AND financial_year=?");p.add(ses);}if(byType){q.append(" AND fee_type=?");p.add(feeType);}Long n=jdbc.queryForObject(q.toString(),Long.class,p.toArray());return String.valueOf(n==null?1:n);}
}
